import React, { useState } from "react";

import Navbar from "../../components/Navbar";
import Sidebar from "../../components/Sidebar";
import { Container, Card, Form, Button, Alert } from "react-bootstrap";

import { calculateInvestment, calculateProfit } from "../../utils/calculators";

function InvestmentCalculator() {

    const [principal, setPrincipal] = useState("");
    const [rate, setRate] = useState("");
    const [years, setYears] = useState("");
    const [futureValue, setFutureValue] = useState("");
    const [profit, setProfit] = useState("");

    const calculate = () => {
        const maturity = calculateInvestment(
            parseFloat(principal),
            parseFloat(rate),
            parseInt(years)
        );

        const gain = calculateProfit(parseFloat(principal), parseFloat(maturity));

        setFutureValue(maturity);
        setProfit(gain);
    };

    return (
        <div>
            <Navbar />

            <div className="d-flex">
                <Sidebar />

                <Container className="p-4">
                    <Card className="border-0 shadow-sm nb-shadow-soft">
                        <Card.Header className="bg-white fw-bold">
                            Investment Calculator
                        </Card.Header>

                        <Card.Body>
                            <Form.Group className="mb-3">
                                <Form.Label>Investment Amount</Form.Label>
                                <Form.Control
                                    type="number"
                                    value={principal}
                                    onChange={(e) => setPrincipal(e.target.value)}
                                />
                            </Form.Group>

                            <Form.Group className="mb-3">
                                <Form.Label>Expected Return %</Form.Label>
                                <Form.Control
                                    type="number"
                                    value={rate}
                                    onChange={(e) => setRate(e.target.value)}
                                />
                            </Form.Group>

                            <Form.Group className="mb-3">
                                <Form.Label>Years</Form.Label>
                                <Form.Control
                                    type="number"
                                    value={years}
                                    onChange={(e) => setYears(e.target.value)}
                                />
                            </Form.Group>

                            <Button variant="primary" className="rounded-pill" onClick={calculate}>
                                Calculate
                            </Button>

                            {futureValue && (
                                <Alert variant="success" className="mt-3">
                                    <h5>Future Value: ₹{futureValue}</h5>
                                    <h5>Profit: ₹{profit}</h5>
                                </Alert>
                            )}
                        </Card.Body>
                    </Card>
                </Container>
            </div>
        </div>
    );
}

export default InvestmentCalculator;
